referenceSolutions.javascript:
export function solve(root, property, value) {
  const nodes = [];
  const visit = (n) => {
    nodes.push(n);
    for (const c of n.children) visit(c);
  };
  visit(root);
  return nodes
    .filter((n) => Object.hasOwn(n.style, property) && n.style[property] === value)
    .map((n) => n.id);
}

referenceSolutions.typescript:
export function solve(root: any, property: string, value: string): any {
  const nodes: any[] = [];
  const visit = (n: any): void => {
    nodes.push(n);
    for (const c of n.children) visit(c);
  };
  visit(root);
  return nodes
    .filter((n) => Object.hasOwn(n.style, property) && n.style[property] === value)
    .map((n) => n.id);
}
